// errUnsupported returns the backend-agnostic *storage.ErrUnsupported sentinel;
// Backend is "flatfile". The skip list is everything FlatFileStore actually
// implements — the whole interface except FederationStore (flat-file syncs
// through plain git remotes, so a Dolt-remote-backed peer registry has no analog).
func errUnsupported(op string) error {
	return &storage.ErrUnsupported{Op: op, Backend: "flatfile"}
}
